export function BrandLockup({
  href = "/",
  compact = false,
  className,
  ...props
}: ComponentProps<"div"> & {
  href?: string;
  /**
   * Narrow slots (docs sidebar): same full logo, slightly shorter so
   * “Made by” stays on one line.
   */
  compact?: boolean;
}) {
  return (
    <div
      {...props}
      className={cn(
        "inline-flex min-w-0 max-w-full items-center gap-0.5 text-gray-12 sm:gap-1",
        className,
      )}
    >
      <Link
        href={href}
        className={cn(
          linkClass,
          "inline-flex shrink-0 items-center gap-0.5 font-bold",
        )}
      >
        <AuraMark />
        <span>
          Aura
          <span className="sr-only"> Design System</span>
        </span>
      </Link>
      <span
        aria-hidden="true"
        className="h-1.5 shrink-0 border-l border-gray-6 sm:h-2"
      />
      <a
        href={SGD_URL}
        target="_blank"
        rel="noopener noreferrer"
        aria-label="Made by Somos Gente Digital (opens in a new tab)"
        className={cn(
          linkClass,
          "inline-flex shrink-0 items-center gap-0.5",
        )}
      >
        <span
          aria-hidden="true"
          className="whitespace-nowrap text-xs text-gray-11"
        >
          Made by
        </span>
        <SgdLogo compact={compact} />
      </a>
    </div>
  );
}
